create table if not exists public."editorialRequests" (id text primary key,"articleId" varchar(180),"requestType" text not null,"name" text not null,"email" text not null,"phone" text,"organization" text,"reason" text not null,"requestedChange" text not null,"evidence" text,"status" text not null default 'pending',"assignedToOpenId" text,"responseText" text,"respondedByOpenId" text,"respondedAtMs" bigint,"createdAtMs" bigint not null,"updatedAtMs" bigint not null);